FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 153: fills of non-planar loops: a pillow, a saddle of arcs and lines, a twisted loop, a triangle of splines. Generated by tools/fixtures/gen-batch-153.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

// Each face's area and its point and normal at the middle of its parameters, rounded to 1e-6.
function fillProbe(context is Context, faces is Query) returns array
{
    var out = [];
    for (var f in evaluateQuery(context, faces))
    {
        const p = evFaceTangentPlane(context, { "face" : f, "parameter" : vector(0.5, 0.5) });
        const r = function(x) { return round(x * 1e6) / 1e6; };
        out = append(out, [r(evArea(context, { "entities" : f }) / millimeter ^ 2),
                [r(p.origin[0] / millimeter), r(p.origin[1] / millimeter), r(p.origin[2] / millimeter)],
                [r(p.normal[0]), r(p.normal[1]), r(p.normal[2])]]);
    }
    return out;
}

// fill: a pillow: arcs rising 5 over each side of a 30 × 20 rectangle
export function c001(context is Context, id is Id)
{
    const e1 = newSketchOnPlane(context, id + "e1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skArc(e1, "a1", { "start" : vector(0, 0) * millimeter, "mid" : vector(15, 5) * millimeter, "end" : vector(30, 0) * millimeter });
    skSolve(e1);
    const e2 = newSketchOnPlane(context, id + "e2", { "sketchPlane" : plane(vector(30, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skArc(e2, "a1", { "start" : vector(0, 0) * millimeter, "mid" : vector(10, 5) * millimeter, "end" : vector(20, 0) * millimeter });
    skSolve(e2);
    const e3 = newSketchOnPlane(context, id + "e3", { "sketchPlane" : plane(vector(0, 20, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skArc(e3, "a1", { "start" : vector(30, 0) * millimeter, "mid" : vector(15, 5) * millimeter, "end" : vector(0, 0) * millimeter });
    skSolve(e3);
    const e4 = newSketchOnPlane(context, id + "e4", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skArc(e4, "a1", { "start" : vector(20, 0) * millimeter, "mid" : vector(10, 5) * millimeter, "end" : vector(0, 0) * millimeter });
    skSolve(e4);
    fill(context, id + "fill1", { "edges" : [{ "entities" : qUnion([qOwnedByBody(qBodyType(qCreatedBy(id + "e1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), qOwnedByBody(qBodyType(qCreatedBy(id + "e2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), qOwnedByBody(qBodyType(qCreatedBy(id + "e3", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), qOwnedByBody(qBodyType(qCreatedBy(id + "e4", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)]), "continuity" : GeometricContinuity.G0 }], "surfaceOperationType" : NewSurfaceOperationType.NEW });
    return { "faces" : fillProbe(context, qOwnedByBody(qBodyType(qCreatedBy(id + "fill1", EntityType.BODY), BodyType.SHEET), EntityType.FACE)) };
}

